#pragma once

namespace mdaz {

class IPlatform;

// C2 sprite animation tables from data/char_anims.txt
// (generated by tools/extract_char_anims.js from data.js).
struct CharAnimFrame {
  int sheet;
  int sx, sy, sw, sh;
  int duration; // Construct frame ticks (usually 1)
};

struct CharAnim {
  char base[40];
  char name[32];
  int frame_count;
  int speed;   // Construct animation Speed (FPS-ish)
  bool loop;
  int first;   // index into frames_
};

class CharAnims {
public:
#if defined(MDAZ_PSP)
  static const int kMaxAnims = 160;
  static const int kMaxFrames = 1024;
#else
  static const int kMaxAnims = 320;
  static const int kMaxFrames = 2048;
#endif

  CharAnims();
  bool load(IPlatform& platform, const char* path);
  bool loaded() const { return count_ > 0; }

  const CharAnim* find(const char* base, const char* anim_name) const;
  // Sample frame by elapsed seconds. Returns null if missing.
  const CharAnimFrame* sample(const CharAnim* anim, float time_sec, int* out_index = 0) const;

  // Draw one sampled frame centered at (sx,sy) with dest size dw×dh.
  void draw(IPlatform& platform, const char* base, const char* anim_name,
            float time_sec, float sx, float sy, float dw, float dh) const;

  // Direction suffix used by C2: "_down" "_up" "_right" "_left"
  static const char* dir_suffix(float facing_deg);
  // Build "run_down" etc. into out (cap bytes).
  static void make_name(char* out, int cap, const char* prefix, float facing_deg);
  // C2 zed/wolf SetAnim attack_up / attack_down / …
  static void make_attack_name(char* out, int cap, float facing_deg) {
    make_name(out, cap, "attack", facing_deg);
  }

private:
  CharAnim anims_[kMaxAnims];
  int count_;
  CharAnimFrame frames_[kMaxFrames];
  int frame_count_;
};

} // namespace mdaz
